insert into public.processes (process_code, title, phase_id, source_reference, context) select '6.2', 'Client Query Management & Follow-up', id, 'Analytix AI Before/After workbook, SOP Before vs After (Full), row 6.2', '{"before_ai_steps":["Associate follow ups for audit requirements with clients","Associate spots an anomaly manually during review of documents","Drafts a query by email or WhatsApp","Chases the client for a response","Repeats until documents are completed & escalates verbally for delays or non- response","Tracks status manually"],"after_ai_steps":["Audit requirements will be readily available in the AI platform for clients hence avoiding manual push for requirements 2 AI detects the anomaly during document check","AI drafts the query automatically","Query tracked with tiered reminders","Human approves before it is sent"]}'::jsonb from public.phases where name = 'File management and closure';
