insert into public.processes (process_code, title, phase_id, source_reference, context) select '6.3', 'Audit Log & Traceability', id, 'Analytix AI Before/After workbook, SOP Before vs After (Full), row 6.3', '{"before_ai_steps":["Events noted manually in email or a personal tracker","Records scattered across inboxes and files","Reconstructing who-did-what is difficult to trace"],"after_ai_steps":["Every action auto-logged with timestamp & user","All events in one searchable, append-only trail","Covers uploads, accepts, rejects, queries, approvals (Ensures compliance with ISA 230:Audit Documentation )"]}'::jsonb from public.phases where name = 'File management and closure';
